const TH_MONTH = {January:"มกราคม",February:"กุมภาพันธ์",March:"มีนาคม",April:"เมษายน",May:"พฤษภาคม",June:"มิถุนายน",July:"กรกฎาคม",August:"สิงหาคม",September:"กันยายน",October:"ตุลาคม",November:"พฤศจิกายน",December:"ธันวาคม",
  Jan:"ม.ค.",Feb:"ก.พ.",Mar:"มี.ค.",Apr:"เม.ย.",Jun:"มิ.ย.",Jul:"ก.ค.",Aug:"ส.ค.",Sep:"ก.ย.",Oct:"ต.ค.",Nov:"พ.ย.",Dec:"ธ.ค."};
const TH_DAY = {Monday:"วันจันทร์",Tuesday:"วันอังคาร",Wednesday:"วันพุธ",Thursday:"วันพฤหัสบดี",Friday:"วันศุกร์",Saturday:"วันเสาร์",Sunday:"วันอาทิตย์",Mon:"จ.",Tue:"อ.",Wed:"พ.",Thu:"พฤ.",Fri:"ศ.",Sat:"ส.",Sun:"อา."};
/* "Monday 16 November", "6 Dec · AM", "Tue 3 Mar 2027": a date with a day number and a month name. */
const TH_DATE = /^(?:(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday|Mon|Tue|Wed|Thu|Fri|Sat|Sun),? )?(\d{1,2}) (January|February|March|April|May|June|July|August|September|October|November|December|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sep|Oct|Nov|Dec)( \d{4})?( · (?:AM|PM))?$/;
function thText(t){
  const k = t.trim(); if (!k) return null;
  if (Object.prototype.hasOwnProperty.call(TH, k)) return t.replace(k, TH[k]);
  for (const [rx, to] of TH_RX){ if (rx.test(k)) return t.replace(k, k.replace(rx, to)); }
  const d = TH_DATE.exec(k);
  if (d) return t.replace(k, [d[1] ? TH_DAY[d[1]] : '', d[2], TH_MONTH[d[3]], d[4] ? d[4].trim() : '', d[5] ? (d[5].includes('AM') ? '· เช้า' : '· บ่าย') : ''].filter(Boolean).join(' '));
  return null;
}
function thApply(root){
  if (!root) return;
  const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const todo = []; let n;
  while ((n = w.nextNode())){ const p = n.parentElement; if (!p || p.closest('script,style,textarea,.notr,.askout,.askme,.katex')) continue; if (/[A-Za-z]/.test(n.nodeValue)) todo.push(n); }
  todo.forEach(n => { const o = n.parentElement.dataset.th; const r = o ? n.nodeValue.replace(n.nodeValue.trim(), o) : thText(n.nodeValue); if (r != null && r !== n.nodeValue) n.nodeValue = r; });
  root.querySelectorAll('[placeholder],[aria-label],[title]').forEach(e => ['placeholder', 'aria-label', 'title'].forEach(a => { const v = e.getAttribute(a); if (v && /[A-Za-z]/.test(v)){ const r = thText(v); if (r != null) e.setAttribute(a, r); } }));
}
